import { Link, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";

function Navbar() {
  const [isLoggedIn, setIsLoggedIn] = useState(
    !!localStorage.getItem("userId")
  );
  const [username, setUsername] = useState(
    localStorage.getItem("full_name") || ""
  );
  const navigate = useNavigate();

  // Update login status and username when localStorage changes
  useEffect(() => {
    const handleStorageChange = () => {
      setIsLoggedIn(!!localStorage.getItem("userId"));
      setUsername(localStorage.getItem("full_name") || "");
    };

    window.addEventListener("storage", handleStorageChange);

    return () => {
      window.removeEventListener("storage", handleStorageChange);
    };
  }, []);

  // Check on component mount (in case of refresh)
  useEffect(() => {
    setIsLoggedIn(!!localStorage.getItem("userId"));
    setUsername(localStorage.getItem("full_name") || "");
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("userId");
    localStorage.removeItem("full_name");
    setIsLoggedIn(false);
    setUsername("");
    navigate("/login");
  };

  const userId = localStorage.getItem("userId");

  return (
    <nav className="bg-black bg-opacity-80 flex justify-between items-center h-12 px-8 shadow-lg">
      {/* Left corner: Username when logged in */}
      <div className="text-white text-lg">
        {isLoggedIn && username ? `Logged in as ${username}` : ""}
      </div>

      {/* Right corner: Navigation links */}
      <div className="flex items-center">
        <Link
          to="/"
          className="text-white mx-4 text-lg uppercase hover:text-blue-400"
        >
          Back to First Page
        </Link>

        {isLoggedIn ? (
          <>
            <Link
              to="/homes"
              className="text-white mx-4 text-lg uppercase hover:text-blue-400"
            >
              Homes
            </Link>
            <Link
              to="/upload"
              className="text-white mx-4 text-lg uppercase hover:text-blue-400"
            >
              Upload
            </Link>
            <Link
              to={`/dashboard/${userId}`}
              className="text-white mx-4 text-lg uppercase hover:text-blue-400"
            >
              Dashboard
            </Link>
            <button
              onClick={handleLogout}
              className="text-white mx-4 text-lg uppercase hover:text-blue-400"
            >
              Logout
            </button>
          </>
        ) : (
          <>
            <Link
              to="/login"
              className="text-white mx-4 text-lg uppercase hover:text-blue-400"
            >
              Login
            </Link>
            <Link
              to="/signup"
              className="text-white mx-4 text-lg uppercase hover:text-blue-400"
            >
              Signup
            </Link>
          </>
        )}
      </div>
    </nav>
  );
}

export default Navbar;
